import type { SidebarsConfig } from "@docusaurus/plugin-content-docs";

// One autogenerated sidebar over docs/. Ordering comes from each page's
// `sidebar_position` front matter, so adding a page to the handbook needs no
// edit here — and, more to the point for this sample, a translated page keeps
// whatever the source page declares: the sidebar is built from the source tree
// once and reused for every locale, so a language behind its source still
// renders the same navigation.
const sidebars: SidebarsConfig = {
  handbook: [{ type: "autogenerated", dirName: "." }],
};

export default sidebars;
